// Gerado por scripts/build-workflows.mjs — edite src/workflows/ e src/lib/.
// ===== lib/util.js =====
// util.js — funções utilitárias puras (sem dependências).
// Este arquivo é embutido nos nós Code do n8n pelo gerador (scripts/build-workflows.mjs).

function normalizeText(s) {
  return String(s == null ? '' : s)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function truncate(s, max) {
  const t = String(s == null ? '' : s);
  return t.length <= max ? t : t.slice(0, Math.max(0, max - 1)).trimEnd() + '…';
}

function isUuid(s) {
  return typeof s === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);
}

function isIsoDate(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = new Date(s + 'T00:00:00Z');
  return !isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
}

function addDays(isoDate, n) {
  const d = new Date(isoDate + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

function weekdayOf(isoDate) {
  return new Date(isoDate + 'T00:00:00Z').getUTCDay(); // 0 = domingo
}

function safeJsonParse(s) {
  if (s && typeof s === 'object') return s;
  try {
    return JSON.parse(s);
  } catch (e) {
    return null;
  }
}

function maskPhone(p) {
  const s = String(p || '');
  return s ? '****' + s.slice(-4) : '';
}

// Remove números longos e e-mails de mensagens de erro antes de registrar
function sanitizeForLog(s, max) {
  return truncate(
    String(s == null ? '' : s)
      .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[email]')
      .replace(/\+?\d[\d\s().-]{7,}\d/g, '[numero]')
      .replace(/(Bearer|token|access_token|key)[=:\s]+[A-Za-z0-9._-]{8,}/gi, '$1 [oculto]'),
    max || 300
  );
}

// Data local (AAAA-MM-DD) de um instante ISO no fuso informado
function localDate(iso, tz) {
  try {
    return new Intl.DateTimeFormat('en-CA', { timeZone: tz || 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(iso));
  } catch (e) {
    return String(iso || '').slice(0, 10);
  }
}

// ===== lib/messages.js =====
// messages.js — textos oficiais (pt-BR) e formato normalizado de mensagens de saída.
// Formatos: {type:'text', text} | {type:'buttons', text, buttons:[{id,title}]} |
//           {type:'list', text, button, rows:[{id,title,description}]} |
//           {type:'location', latitude, longitude, name, address} | {type:'template', ...}
// Requer: util.js

function msgText(text) { return { type: 'text', text: truncate(text, 4000) }; }
function msgButtons(text, buttons) {
  return { type: 'buttons', text: truncate(text, 1024), buttons: (buttons || []).slice(0, 3).map((b) => ({ id: String(b.id).slice(0, 256), title: truncate(b.title, 20) })) };
}
function msgList(text, button, rows) {
  return { type: 'list', text: truncate(text, 1024), button: truncate(button, 20),
    rows: (rows || []).slice(0, 10).map((r) => ({ id: String(r.id).slice(0, 200), title: truncate(r.title, 24), description: r.description ? truncate(r.description, 72) : undefined })) };
}

const DEFAULT_EMERGENCY = 'Se houver sangramento intenso que não para, inchaço que dificulta respirar ou engolir, febre alta com inchaço no rosto ou trauma forte na boca ou rosto, procure agora um pronto-socorro ou ligue 192 (SAMU).';

function clinicMsg(ctx, key, fallback) {
  const m = (ctx.clinic && ctx.clinic.messages) || {};
  return m[key] || fallback || '';
}

function menuMessage(text) {
  return msgButtons(text || 'Como posso ajudar?', [
    { id: 'MENU:SCHEDULE', title: 'Agendar consulta' },
    { id: 'MENU:APPTS', title: 'Minhas consultas' },
    { id: 'MENU:HUMAN', title: 'Falar com a equipe' },
  ]);
}

function greetingMessages(ctx, aiReply) {
  const p = ctx.patient || {};
  const out = [];
  const name = p.first_name ? `, ${p.first_name}` : '';
  if (p.is_new || !p.privacy_notice_shown) {
    out.push(msgText(clinicMsg(ctx, 'welcome', `Olá! Sou a assistente virtual da ${ctx.clinic.name}.`)));
    const notice = clinicMsg(ctx, 'privacy_notice', '');
    if (notice) out.push(msgText(notice));
  } else {
    out.push(msgText(aiReply && aiReply.length > 3 ? aiReply : `Olá${name}! Que bom falar com você novamente.`));
  }
  out.push(menuMessage('Como posso ajudar?'));
  return out;
}

function askServiceMessage(ctx, prefix) {
  const rows = (ctx.services || []).filter((s) => s.bookable_by_bot).map((s) => ({
    id: 'SVC:' + s.code, title: s.name, description: s.duration_minutes ? `Cerca de ${s.duration_minutes} min` : undefined,
  }));
  return msgList((prefix ? prefix + '\n\n' : '') + 'Para qual atendimento você gostaria de agendar?', 'Ver serviços', rows);
}

function askNameMessage() {
  return msgText('Para fazer o seu cadastro, qual é o seu nome completo?');
}

function periodLabel(p) {
  return { morning: 'pela manhã', afternoon: 'à tarde', evening: 'à noite' }[p] || '';
}

function offerMessages(offer, serviceName, opts) {
  const o = opts || {};
  const lines = offer.options.map((x) => `${x.option_number}) ${x.label} com ${x.professional_name}`);
  let head = o.slotTaken ? 'Que pena, esse horário acabou de ser ocupado. ' : '';
  if (offer.alternative_dates) head += 'Não encontrei horários na data pedida, mas tenho estas opções próximas';
  else head += 'Tenho estes horários disponíveis';
  head += serviceName ? ` para ${serviceName}:` : ':';
  if (offer.period_relaxed && o.period) head = `Não há horários ${periodLabel(o.period)} nesse período. ` + head;
  const body = `${head}\n\n${lines.join('\n')}\n\nToque no horário desejado ou responda com o número. Assim que você escolher, eu confirmo na agenda.`;
  return [msgButtons(body, offer.options.map((x) => ({ id: 'OPT:' + x.option_id, title: x.short_label || x.label })))];
}

function noSlotsMessage(ctx, serviceName) {
  return msgText(`Não encontrei horários livres para ${serviceName || 'esse atendimento'} nos próximos dias. ` +
    `Nosso horário de funcionamento é: ${ctx.clinic.hours_summary}. Quer que eu tente outra data ou período, ou prefere falar com a equipe?`);
}

function bookedMessages(ctx, b) {
  const c = ctx.clinic;
  const out = [msgText(
    `Pronto${ctx.patient && ctx.patient.first_name ? ', ' + ctx.patient.first_name : ''}! Sua consulta está agendada ✅\n\n` +
    `📅 ${b.label}\n🦷 ${b.service_name}\n👩‍⚕️ ${b.professional_name}\n📍 ${c.name} — ${c.address}` +
    (c.maps_url ? `\n🗺️ ${c.maps_url}` : '') +
    `\n\nVocê receberá um lembrete um dia antes. Para remarcar ou cancelar, é só me escrever por aqui.` +
    (clinicMsg(ctx, 'cancel_policy') ? `\n\n${clinicMsg(ctx, 'cancel_policy')}` : ''))];
  const loc = locationMessage(ctx);
  if (loc) out.push(loc);
  return out;
}

function locationMessage(ctx) {
  const c = ctx.clinic || {};
  if (c.latitude === null || c.latitude === undefined || c.longitude === null || c.longitude === undefined) return null;
  return { type: 'location', latitude: Number(c.latitude), longitude: Number(c.longitude), name: c.name, address: c.address };
}

function locationMessages(ctx) {
  const c = ctx.clinic;
  const out = [msgText(`📍 ${c.name}\n${c.address}` + (c.maps_url ? `\n\nComo chegar: ${c.maps_url}` : ''))];
  const loc = locationMessage(ctx);
  if (loc) out.push(loc);
  return out;
}

function hoursMessage(ctx) {
  const c = ctx.clinic;
  return msgText(`Nosso horário de funcionamento é:\n${c.hours_summary.split('; ').join('\n')}` +
    (c.is_open_now ? '\n\nEstamos abertos agora.' : (c.next_opening_label ? `\n\nAbrimos novamente ${c.next_opening_label}.` : '')));
}

function appointmentsListText(appts) {
  return appts.map((a, i) => `${i + 1}) ${a.label} — ${a.service_name} com ${a.professional_name}`).join('\n');
}

function chooseAppointmentMessage(appts, purpose) {
  const verb = purpose === 'cancel' ? 'cancelar' : 'remarcar';
  const text = `Você tem estas consultas:\n\n${appointmentsListText(appts)}\n\nQual delas deseja ${verb}?`;
  if (appts.length <= 3) return msgButtons(text, appts.map((a, i) => ({ id: 'APPT:' + a.id, title: `${i + 1}) ${a.short_label}` })));
  return msgList(text, 'Escolher', appts.map((a, i) => ({ id: 'APPT:' + a.id, title: a.short_label, description: `${a.service_name} – ${a.professional_name}` })));
}

function cancelConfirmMessage(label, late, ctx) {
  const policy = late ? `\n\nAtenção: ${clinicMsg(ctx, 'cancel_policy', 'o cancelamento está sendo feito com pouca antecedência.')}` : '';
  return msgButtons(`Confirma o cancelamento da consulta de ${label}?${policy}`, [
    { id: 'YES', title: 'Sim, cancelar' },
    { id: 'NO', title: 'Não, manter' },
  ]);
}

function serviceInfoMessages(ctx, svc) {
  const parts = [`Sim! Fazemos ${svc.name.toLowerCase()}.`];
  if (svc.description) parts.push(svc.description);
  if (svc.price_info) parts.push(svc.price_info);
  const out = [msgText(parts.join(' '))];
  if (svc.bookable_by_bot) out.push(msgButtons('Quer que eu veja os horários disponíveis?', [{ id: 'SVC:' + svc.code, title: 'Ver horários' }, { id: 'MENU:HUMAN', title: 'Falar com a equipe' }]));
  else out.push(msgButtons('Esse agendamento é feito pela nossa equipe. Posso chamar alguém para você?', [{ id: 'MENU:HUMAN', title: 'Sim, por favor' }]));
  return out;
}

function notUnderstoodMessage(ctx, aiReply) {
  return menuMessage((aiReply && aiReply.length > 3 ? aiReply + '\n\n' : 'Desculpe, não entendi muito bem. ') +
    'Posso ajudar com agendamentos, remarcações, cancelamentos e informações da clínica.');
}

function technicalErrorMessage() {
  return msgText('Desculpe, tive uma instabilidade técnica agora. Já avisei a nossa equipe, que vai continuar o seu atendimento por aqui.');
}

function unsupportedMediaMessage() {
  return msgText('Por aqui eu consigo entender mensagens de texto e áudio. Por segurança, não envie fotos, exames ou documentos. Como posso ajudar?');
}

// ===== lib/whatsapp.js =====
// whatsapp.js — monta payloads oficiais da WhatsApp Cloud API (Graph API /messages).
// Requer: util.js

function toGraphPayload(to, msg) {
  const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to: String(to).replace(/\D/g, '') };
  switch (msg && msg.type) {
    case 'text':
      return Object.assign(base, { type: 'text', text: { preview_url: false, body: truncate(msg.text, 4096) } });
    case 'buttons':
      return Object.assign(base, { type: 'interactive', interactive: {
        type: 'button', body: { text: truncate(msg.text, 1024) },
        action: { buttons: msg.buttons.slice(0, 3).map((b) => ({ type: 'reply', reply: { id: b.id, title: truncate(b.title, 20) } })) },
      } });
    case 'list':
      return Object.assign(base, { type: 'interactive', interactive: {
        type: 'list', body: { text: truncate(msg.text, 1024) },
        action: { button: truncate(msg.button || 'Opções', 20), sections: [{ title: 'Opções', rows: msg.rows.slice(0, 10).map((r) => {
          const row = { id: r.id, title: truncate(r.title, 24) };
          if (r.description) row.description = truncate(r.description, 72);
          return row;
        }) }] },
      } });
    case 'location':
      return Object.assign(base, { type: 'location', location: {
        latitude: msg.latitude, longitude: msg.longitude, name: truncate(msg.name || '', 100), address: truncate(msg.address || '', 200),
      } });
    case 'template':
      return Object.assign(base, { type: 'template', template: { name: msg.name, language: { code: msg.language || 'pt_BR' }, components: msg.components || [] } });
    default:
      throw new Error('Tipo de mensagem não suportado: ' + (msg && msg.type));
  }
}

function graphKind(msg) {
  return { text: 'text', buttons: 'interactive', list: 'interactive', location: 'location', template: 'template' }[msg.type] || 'text';
}

// Template Utility de lembrete (aprovado na Meta) com botões de resposta rápida
function buildReminderTemplate(rem) {
  const tpl = rem.template || {};
  const params = (tpl.body_params || []).map((k) => ({ type: 'text', text: truncate(String(rem[k] == null ? '' : rem[k]), 60) || '-' }));
  const components = [];
  if (params.length) components.push({ type: 'body', parameters: params });
  (tpl.quick_reply_buttons || []).forEach((b, idx) => {
    components.push({ type: 'button', sub_type: 'quick_reply', index: String(idx), parameters: [{ type: 'payload', payload: `${b}:${rem.appointment_id}` }] });
  });
  return { type: 'template', name: tpl.name, language: tpl.language || 'pt_BR', components };
}

// Lembrete dentro da janela de 24h (mensagem de sessão, sem template)
function buildReminderSession(rem) {
  const name = rem.patient_first_name ? `Olá, ${rem.patient_first_name}! ` : 'Olá! ';
  return {
    type: 'buttons',
    text: `${name}Lembrete da sua consulta na ${rem.clinic_name}:\n\n📅 ${rem.label}\n🦷 ${rem.service_name}\n👩‍⚕️ ${rem.professional_name}\n📍 ${rem.address}\n\nVocê confirma a sua presença?`,
    buttons: [
      { id: 'CONFIRM:' + rem.appointment_id, title: 'Confirmar presença' },
      { id: 'RESCHEDULE:' + rem.appointment_id, title: 'Remarcar' },
      { id: 'CANCEL:' + rem.appointment_id, title: 'Cancelar' },
    ],
  };
}

function buildStaffAlertTemplate(tplCfg, text) {
  return { type: 'template', name: tplCfg.name, language: tplCfg.language || 'pt_BR',
    components: [{ type: 'body', parameters: [{ type: 'text', text: truncate(text.replace(/\s*\n\s*/g, ' | '), 900) }] }] };
}

// Interpreta a resposta do HTTP Request (com "Never Error" + resposta completa)
function parseGraphResponse(res) {
  const status = res && (res.statusCode || res.status);
  const body = res && (res.body !== undefined ? res.body : res);
  const parsed = typeof body === 'string' ? safeJsonParse(body) : body;
  if (status >= 200 && status < 300 && parsed && parsed.messages && parsed.messages[0]) {
    return { ok: true, wa_message_id: parsed.messages[0].id };
  }
  const err = (parsed && parsed.error) || {};
  return { ok: false, status: status || 0, error_code: String(err.code || status || 'network'), error_title: sanitizeForLog(err.message || err.error_user_msg || 'Falha ao enviar', 200),
    retryable: !status || status >= 500 || status === 429 || String(err.code) === '131048' || String(err.code) === '130429' };
}


// ===== lógica do nó =====
const j = $json.input; const appts = ($json.result && $json.result.appointments) || [];
const p = (j.decision && j.decision.params) || {};
const done = (messages, state, context) => ({ json: Object.assign({}, j, { appts, next: 'done', result: { messages, state: state || 'idle', context: context || {} } }) });
const go = (next, extra) => ({ json: Object.assign({}, j, { appts, next }, extra) });
const own = (id) => appts.find((a) => a.id === id);
const notFound = () => done([msgText('Não encontrei essa consulta entre as suas consultas futuras. Posso ajudar com outra coisa?')]);
const none = () => done([msgButtons('Não encontrei consultas futuras no seu cadastro. Quer agendar uma?', [{ id: 'MENU:SCHEDULE', title: 'Agendar consulta' }])]);
switch (p.action) {
  case 'list': {
    if (!appts.length) return none();
    const btns = [{ id: 'MENU:SCHEDULE', title: 'Agendar outra' }];
    if (appts.length === 1) btns.push({ id: 'RESCHEDULE:' + appts[0].id, title: 'Remarcar' }, { id: 'CANCEL:' + appts[0].id, title: 'Cancelar' });
    return done([msgButtons('Suas próximas consultas:\n\n' + appointmentsListText(appts), btns)]);
  }
  case 'cancel_start':
  case 'reschedule_start': {
    const purpose = p.action === 'cancel_start' ? 'cancel' : 'reschedule';
    if (!appts.length) return none();
    if (p.appointment_id && !own(p.appointment_id)) return notFound();
    const target = p.appointment_id ? own(p.appointment_id) : (appts.length === 1 ? appts[0] : null);
    if (!target) return done([chooseAppointmentMessage(appts, purpose)], 'awaiting_appointment_choice', { purpose, appointment_ids: appts.map((a) => a.id), prefs: p.prefs || {} });
    return purpose === 'cancel' ? go('cancel_check', { appointment: target }) : go('reschedule_check', { appointment: target, prefs: p.prefs || {} });
  }
  case 'cancel_prompt': {
    const t = own(p.appointment_id); if (!t) return notFound();
    return go('cancel_check', { appointment: t });
  }
  case 'cancel_execute': {
    const t = own(p.appointment_id); if (!t) return notFound();
    return go('cancel_exec', { appointment: t });
  }
  case 'confirm_attendance': {
    const t = p.appointment_id ? own(p.appointment_id) : appts[0];
    if (!t) return p.appointment_id ? notFound() : none();
    return go('attend', { appointment: t });
  }
  default:
    return done([menuMessage('Como posso ajudar?')]);
}

